text:
** 20200304 KHSONG 날짜선택 오류수정
** 20200507 KHSONG C20200507-000035 (소형사업부 RTF 관련 Measure 숨기기)
 2020/05/22     P.C.I		[C20200525-000296] (81 사업부) MKT Fcst 입력 시 Unit Price 체크 기준에 Plant Site 조건 추가
** 20200529 KHSONG C20200424-000010 (Sales Price 필수 입력 구간 관련의 건)
 2020/06/08     P.C.I		[C20200511-000360] Sales Site Project Model - 자동차 사업부 Cell , Car 수량 환산 기준정보 필수화
 2020/06/15     P.C.I		[C20200615-000238] [ESS사업부] Sales Company/Plant 저장시 기준정보 재생성 로직 삭제
 2020/07/07     hwi1993		[C20200511-000360] Sales Site Project Model - 자동차 사업부 Cell , Car 수량 환산 기준정보 필수화 -- 제품일경우에만 적용
 2020/07/09     P.C.I		[C20200707-000367] ESS 사업부 Sales Site Project Model validation 추가
 2020/07/16		hwi1993		[C20200713-000189] [VMI-in Req] 에 의해 자동계산된 mkt fcst 는 무시하고, 다시 자동계산해서 insert 함.
 2020/07/20     P.C.I		[C20200717-000157] ESS 사업부 Sales Site Project Model validation 추가
 2025/05/21     KANG.H.J	[PJ2025-00017] CELL_PROD_SITE_ID 추가 - [PJ2025-00017] RTF_BALANCE 계산시 40 사업부와 통일 필요
*/
CREATE PROCEDURE [dbo].[DM0003_SAVE_MKT_FCST]

	-- Add the parameters for the stored procedure here
	@p_active_flag			NVARCHAR(MAX),
	@p_division_id			NVARCHAR(MAX),
	@p_project_code			NVARCHAR(MAX),
	@p_scm_site_id			NVARCHAR(MAX),
	@p_item_id				NVARCHAR(MAX),
	@p_dom_exp				NVARCHAR(MAX),
	@p_fcst_type			NVARCHAR(MAX),
	@p_incoterms			NVARCHAR(MAX),
	@p_measure				NVARCHAR(MAX),
	@p_plant_site_id  	    NVARCHAR(MAX),
	@p_yyyymmdd				NVARCHAR(MAX),
	@p_qty					NVARCHAR(MAX),
	@p_created_by			NVARCHAR(MAX)

AS

BEGIN

    SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
    --SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    SET NOCOUNT ON; 
    SET XACT_ABORT ON;

	DECLARE @v_active_flag			NVARCHAR(MAX);
	DECLARE @v_division_id			NVARCHAR(MAX);
	DECLARE @v_project_code			NVARCHAR(MAX);
	DECLARE @v_scm_site_id			NVARCHAR(MAX);
	DECLARE @v_item_id				NVARCHAR(MAX);
	DECLARE @v_dom_exp				NVARCHAR(MAX);
	DECLARE @v_fcst_type			NVARCHAR(MAX);
	DECLARE @v_incoterms			NVARCHAR(MAX);
	DECLARE @v_measure				NVARCHAR(MAX);
	DECLARE @v_PLANT_SITE_ID		NVARCHAR(MAX);
	DECLARE @v_yyyymmdd				NVARCHAR(MAX);
	DECLARE @v_qty					NVARCHAR(MAX);
	DECLARE @v_created_by			NVARCHAR(MAX);
	
    DECLARE @plan_start_yyyymmdd    NVARCHAR(MAX);  -- 20180611 KHSONG ADDED

	SET @v_active_flag = NULL;
	SET @v_division_id = NULL;
	SET @v_project_code = NULL;
	SET @v_scm_site_id = NULL;
	SET @v_item_id = NULL;
	SET @v_dom_exp = NULL;	 
	SET @v_fcst_type = NULL;	 
	SET @v_incoterms = NULL;	 
	SET @v_measure = NULL;	 
	SET @v_PLANT_SITE_ID = NULL;	 
	SET @v_yyyymmdd = NULL;	
	SET @v_qty = NULL;	  
	SET @v_created_by = NULL;

	DECLARE @read_cnt		INTEGER = 0; 
	DECLARE @read_1000_cnt		INTEGER = 0; 
	
	-- LOG 용 변수 설정
    DECLARE @v_program_name NVARCHAR(150) = 'DMF0003_SAVE_MKT_FCST';
    DECLARE @v_log_type     NVARCHAR(30); -- START/END/ERROR/...
    DECLARE @n_log_count    INTEGER = 0;
    DECLARE @v_log_message  NVARCHAR(1000);
    DECLARE @v_description  NVARCHAR(500);
    DECLARE @d_event_date   DATETIME;

	-- 마지막 데이터 처리를 위한 구분자 추가
	SET @p_active_flag    = RTRIM(@p_active_flag   ) + '^';
	SET @p_division_id    = RTRIM(@p_division_id   ) + '^';
	SET @p_project_code   = RTRIM(@p_project_code  ) + '^';
	SET @p_scm_site_id    = RTRIM(@p_scm_site_id   ) + '^';
	SET @p_item_id        = RTRIM(@p_item_id       ) + '^';
	SET @p_dom_exp        = RTRIM(@p_dom_exp       ) + '^';
	SET @p_fcst_type      = RTRIM(@p_fcst_type     ) + '^';
	SET @p_incoterms      = RTRIM(@p_incoterms     ) + '^';
	SET @p_measure        = RTRIM(@p_measure       ) + '^';
	SET @p_plant_site_id  = RTRIM(@p_plant_site_id ) + '^';
	SET @p_yyyymmdd       = RTRIM(@p_yyyymmdd      ) + '^';
	SET @p_qty            = RTRIM(@p_qty           ) + '^';
	SET @p_created_by     = RTRIM(@p_created_by    ) + '^';

	-- TEMP TABLE 확인후 삭제
	IF OBJECT_ID (N'tempdb..#SEND_TARGET_DATA', N'U') IS NOT NULL 
		DROP TABLE #SEND_TARGET_DATA

	--[C20200511-000360] Sales Site Proj

                                                                                                         BALANCE_CREATE 호출 로직 (END)
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------◎◎◎◎

 
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------◎◎◎◎
	--                                                                20180816 KHSONG DIVISION_ID = '40' PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_SINGLE Procedure 호출 (START)
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------◎◎◎◎
	-- SCP가 Open 했기 때문에 RTF 값을 MKT FCST에서 수정하지 않음.
	IF (SELECT count(1) FROM #results where v_DIVISION_ID = '40') > 0
		BEGIN
			EXEC dbo.PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE  
		END
	--PRINT N'PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE   end                            =>' + CONVERT(VARCHAR(8), GETDATE(), 108)
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------◎◎◎◎
	--                                                                20180816 KHSONG DIVISION_ID = '40' PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_SINGLE Procedure 호출 (END)
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------◎◎◎◎


    --COMMIT TRANSACTION DM0003_SAVE_MKT_FCST ;
		--PRINT N'ALL JOB END                                     =>' + CONVERT(VARCHAR(8), GETDATE(), 108)
		----------------------------------------------------------|

	END TRY

	BEGIN CATCH

		--ROLLBACK TRANSACTION DM0003_SAVE_MKT_FCST
		--ROLLBACK TRANSACTION DM0003_SAVE_MKT_FCST9
  
		-- ROLLBACK
		-- ERROR LOG VALUE SAVE
		SET @v_log_type = 'ERROR';
		SET @v_log_message = CAST(ERROR_MESSAGE() AS NVARCHAR(1000));
		SET @v_description = 'ERROR_LINE : ' + STR(ERROR_LINE());
		SET @d_event_date = SYSDATETIME();
		SELECT '[' + Convert(NVARCHAR(10), ERROR_NUMBER()) + ']_O' + ERROR_MESSAGE();  /*-- 에러메시지 DISPLAY --*/
		EXEC PR_SCM_SYS_LOG_BATCH @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;

	END CATCH

	SET NOCOUNT OFF;

	-- 종료 LOG
	SET @v_log_type = 'END';
	SET @v_log_message = '########## END of procedure ##########';
	SET @v_description = '';
	SET @d_event_date = SYSDATETIME();
	EXEC PR_SCM_SYS_LOG_BATCH @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;
	
  END;

	-- 트랜잭션 (END)
	err_rtn:
	IF @v_log_type = 'INVALID'
		begin
			--ROLLBACK TRANSACTION DM0003_SAVE_MKT_FCST

			SET @v_log_message = '########## END of procedure ##########';
			SET @d_event_date = SYSDATETIME();
			EXEC PR_SCM_SYS_LOG_BATCH @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;
		end

URE_GROUP,' );
  --SET @v_column =  REPLACE(@v_column, 'F.MEASURE', 'ISNULL( ( SELECT MAX(COLUMN_LABEL_NAME)  FROM [dbo].[SCM_MST_SHEET_MEASURE] where PROGRAM_ID = ''DM0003'' and COLUMN_NAME = U.MEASURE), ''  ''+U.MEASURE ) AS MEASURE' );
 
  SET @v_groupby = REPLACE(@v_groupby, 'F.MEASURE', 'U.MEASURE' );
  SET @v_column =  REPLACE(@v_column, 'F.MEASURE', 'U.MEASURE' );

  SET @v_groupby = @v_groupby + ', F.EDIT_FLAG, U.SORT_ORDER_NO';
  --SET @v_orderby = REPLACE(@v_orderby, 'MEASURE', 'U.SORT_ORDER_NO');
  SET @v_orderby = REPLACE(@v_orderby, 'F.MEASURE_GROUP', 'U.SORT_ORDER_NO');
  SET @v_orderby = REPLACE(@v_orderby, ', F.MEASURE', '');

  --SELECT @v_column;
  --SELECT @v_groupby;

  CLOSE c_title;  
  DEALLOCATE c_title;

  SET @v_from_yyyymmdd  = '';
  SET @v_to_yyyymmdd    = '';
  SET @v_from_result    = '';
  SET @v_to_result      = '';
  SET @v_user_time_zone = '';

  --SET @v_from_yyyymmdd = CONVERT(NVARCHAR(8), CURRENT_TIMESTAMP, 112);

  --SELECT @v_from_yyyymmdd = C.BASIS_START_DATE
  --FROM   [dbo].[SCM_SYS_CALENDAR_M]      C	
  --WHERE  1 = 1
  --AND    C.BASIS_YYYYMMDD = CONVERT(NVARCHAR(8), CURRENT_TIMESTAMP, 112) 

  BEGIN
	  SELECT @v_user_time_zone = U.TIMEZONE
	  FROM   [dbo].[TB_FX_User] U WITH(NOLOCK)
	  WHERE  U.UserID = @p_created_by;
  END

  SELECT @v_from_yyyymmdd = MIN(C.BASIS_YYYYMMDD)
  FROM   [dbo].[SCM_SYS_CALENDAR_M] C  WITH(NOLOCK) 
       , (SELECT DISTINCT ISO_YYYYWW		    		
	      FROM   [dbo].[SCM_SYS_CALENDAR_M] WITH(NOLOCK) 
		  WHERE  1 = 1
		  AND    BASIS_YYYYMMDD = CONVERT(CHAR(8), dbo.FN_MULTY_TIME(@v_user_time_zone), 112)
		  --AND    BASIS_YYYYMMDD <= CONVERT(CHAR(8), DATEADD(MM, @v_user_col_cnt, dbo.FN_MULTY_TIME(@v_user_time_zone)), 112)
		 ) T
  WHERE  1 = 1
  AND    C.ISO_YYYYWW = T.ISO_YYYYWW ;


  SELECT @v_from_result = C.BASIS_START_DATE
  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C	WITH(NOLOCK)
  WHERE  1 = 1
  AND    C.BASIS_YYYYMMDD = @p_from_yyyymmdd; 

  SELECT @v_to_result = C.BASIS_START_DATE
  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C	WITH(NOLOCK)
  WHERE  1 = 1
  AND    C.BASIS_YYYYMMDD = @p_to_yyyymmdd; 

  IF @v_from_yyyymmdd > @v_from_result
      BEGIN -- 실적 보여줌
	  SET @v_to_yyyymmdd   = @p_to_yyyymmdd;
      SET @v_to_result     = @v_from_yyyymmdd;
	  END;
  ELSE IF @v_from_yyyymmdd <= @v_from_result
      BEGIN -- 실적 없음
	  SET @v_to_yyyymmdd   = @p_to_yyyymmdd;
	  SET @v_from_result = '19000101'; --CONVERT(CHAR(8), DATEADD(MM, 6, CURRENT_TIMESTAMP), 112);
      SET @v_to_result = '19000101'; --CONVERT(CHAR(8), DATEADD(MM, -6, CURRENT_TIMESTAMP), 112);
	  END;
  ELSE IF @v_from_yyyymmdd > @v_to_result
      BEGIN -- 실적만 보여줌
	  SET @v_from_yyyymmdd = '19000101'; --CONVERT(CHAR(8), DATEADD(MM, 6, CURRENT_TIMESTAMP), 112);
      SET @v_to_yyyymmdd = '19000101'; --CONVERT(CHAR(8), DATEADD(MM, -6, CURRENT_TIMESTAMP), 112);
	  SET @v_from_result = @p_from_yyyymmdd;
	  SET @v_to_result = @p_to_yyyymmdd;
	  END;
  ELSE IF @v_from_yyyymmdd = @v_to_result
      BEGIN
      SET @v_to_yyyymmdd = @v_from_yyyymmdd
	  SET @v_from_result = @p_from_yyyymmdd;
	  SET @v_to_result = @p_to_yyyymmdd;
	  END;

	 
  SET @v_sql_text = '
WITH SELECT_MEASURE AS (SELECT U.PROGRAM_ID
                             , U.SHEET_NAME
                             , U.USER_ID
                             --, U.COLUMN_NAME AS MEASURE_GROUP
                         , CASE WHEN U.COLUMN_NAME IN ( ''CUST_INV_I'',''CUST_PRODUCT_S'',''CUST_WHIN_P'',''CUST_DIO''  )  THEN ''CUST. PSI'' 
                                WHEN  U.COLUMN_NAME IN ( ''MKT_INV_I'',''MKT_PRODUCT_S'',''MKT_WHIN_P'',''MKT_DIO''  )  THEN ''MKT PSI''  
                              ELSE   U.COLUMN_NAME 
                           END AS MEASURE_GROUP
                         , U.COLUMN_NAME AS MEASURE
                         , U.SORT_ORDER_NO
                          FROM [dbo].[SCM_MST_TITLESET_USER] U  WITH(NOLOCK,INDEX (PK_SCM_MST_TITLE

ET_WHERE_SQL]('F.PROJECT_CODE', 'LK', @p_project_code)); 
  ELSE
    SET @v_sql_text = REPLACE(@v_sql_text,'[@v_project_code]' , [dbo].[FN_SCM_GET_WHERE_SQL]('F.PROJECT_CODE', 'LK', @p_customer)); 
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_item_id]'      , [dbo].[FN_SCM_GET_WHERE_SQL]('F.ITEM_ID', 'LK', @p_item_id)); 

  ----20180626
  IF @p_owner = ''
	  begin
		  SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_def_text]', 'AND 1=1 ');
		  SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_sml_text]', 'AND 1=1 ');
	  end
  else
	  begin
  --SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_def_text]', 'AND EXISTS (SELECT * FROM [dbo].[UF_FX_STRING_SPLIT] (''ZZZZZ'','','') AS P WHERE b.PROJECT_OWNER LIKE N''%'' + P.token +''%'')');
  SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_def_text]', 'AND ( j.USER_ID IN ( SELECT token FROM dbo.String_Split(N'''+@p_owner+''','',''))  OR j.USER_NAME IN ( SELECT token FROM dbo.String_Split(N'''+@p_owner+''','',''))  OR j.USER_NAME_EN IN ( SELECT token FROM dbo.String_Split('''+@p_owner+''','','')) )   ' );
  SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_sml_text]',  ' AND    ( SU.USER_ID IN ( SELECT token FROM dbo.String_Split('''+@p_owner+''','','') ) OR SU.USER_NAME IN ( SELECT token FROM dbo.String_Split(N'''+@p_owner+''','','') ) OR SU.USER_NAME_EN IN ( SELECT token FROM dbo.String_Split('''+@p_owner+''','','') )  ) ' );
  SET @v_sql_text = REPLACE(@v_sql_text, 'ZZZZZ', @p_owner);
	  end

  --SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_def_text]', 'AND EXISTS (SELECT * FROM [dbo].[UF_FX_STRING_SPLIT] (''ZZZZZ'','','') AS P WHERE b.PROJECT_OWNER LIKE N''%'' + P.token +''%'')');
  --SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_sml_text]', 'AND EXISTS (SELECT * FROM [dbo].[UF_FX_STRING_SPLIT] (''ZZZZZ'' ,'','') AS P WHERE SI.OWNER LIKE N''%'' + P.token + ''%'')');
  --SET @v_sql_text = REPLACE(@v_sql_text, 'ZZZZZ', @p_owner);
  -- SET @v_sql_text = REPLACE(@v_sql_text, 'ZZZZZ', @p_owner);

  --  SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_sml_text]', @p_owner);

  ------------------------------------------------------------------------------------------------------------------------------*****

  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_division_id_t]'  , [dbo].[FN_SCM_GET_WHERE_SQL]('T.DIVISION_ID'  , 'IN', @p_division_id));
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_scm_site_id_t]'  , [dbo].[FN_SCM_GET_WHERE_SQL]('T.SCM_SITE_ID'  , 'IN', @p_scm_site_id)); 
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_plant_site_id_t]', [dbo].[FN_SCM_GET_WHERE_SQL]('T.PLANT_SITE_ID', 'IN', @p_plant_site_id));
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_project_code_t]' , [dbo].[FN_SCM_GET_WHERE_SQL]('T.PROJECT_CODE', 'LK', @p_project_code));  
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_item_id_t]'      , [dbo].[FN_SCM_GET_WHERE_SQL]('T.ITEM_ID', 'LK', @p_item_id)); 
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_item_type_I]'    , [dbo].[FN_SCM_GET_WHERE_SQL]('L.ITEM_TYPE'    , 'IN', @p_item_type  ));
  
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_from_yyyymmdd]', @v_from_yyyymmdd);
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_to_yyyymmdd]'  , @v_to_yyyymmdd  );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_from_result]'  , @v_from_result  );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_to_result]'    , @v_to_result    );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_column]'       , @v_column       );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_groupby]'      , @v_groupby      );
  --SET @v_sql_text = REPLACE(@v_sql_text,'[@v_orderby]'      , @v_orderby      );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@p_created_by]'   , @p_created_by   );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_dept_id]'      , @v_dept_id      );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_group_id]'      , @v_group_id      );

  -- 0703 skh added
  SET @v_sql_text = REPLACE(@v_sql_text,'[@p_from_yyyymmdd]', @p_from_yyyymmdd);
  SET @v_sql_text = R

EPLACE(@v_sql_text,'[@p_to_yyyymmdd]', @p_to_yyyymmdd);
  
  
  --SET @p_debug = @v_iteration;
  --RETURN @p_debug;
  --SELECT @v_sql_text;
     
  --select @v_column_name, @v_column


	--select @v_column;
	--select @v_sql_text;
 EXEC SP_EXECUTESQL @v_sql_text; 

-- xml확인할경우
SELECT CONVERT(TEXT, @v_sql_text)
FOR XML PATH('')--,ROOT('x')  
 
END

/****************************************************************************************************/
/* Program ID  : DM0003_GET_MKT_FCST_DATA                                                             */
/* Description : Procedure 작성 가이드                                                              */
/* Usage       : Procedure 작성 시 참조하세요!                                                      */
/* Parameter   :                                                                                    */
/*                                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2017/11/24  SongDH       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트 */
/*                                                                                                  */
/****************************************************************************************************/
CREATE procedure [dbo].[DM0003_GET_MKT_FCST_DATA_XML]
    @p_division_id    NVARCHAR(MAX),
    @p_scm_site_id    NVARCHAR(MAX),
    @p_plant_site_id  NVARCHAR(MAX),
    @p_team_id        NVARCHAR(MAX),
    @p_customer       NVARCHAR(MAX),
    @p_biz_type       NVARCHAR(MAX),
    @p_project_code   NVARCHAR(MAX),
    @p_item_id        NVARCHAR(MAX),
    @p_from_yyyymmdd  NVARCHAR(8),
    @p_to_yyyymmdd    NVARCHAR(8),
    @p_created_by	  NVARCHAR(50),
	@p_user_group     NVARCHAR(50),
	@p_item_type      NVARCHAR(MAX)
  --,@p_debug         NVARCHAR(MAX) OUTPUT
AS  
  
BEGIN
    SET NOCOUNT ON;

    DECLARE @v_sql_text_result   AS NVARCHAR(MAX);
    DECLARE @v_sql_text          AS NVARCHAR(MAX);
    DECLARE @v_sql_text3         AS NVARCHAR(MAX);
    DECLARE @v_iteration         AS NVARCHAR(MAX);
    DECLARE @v_column            AS NVARCHAR(MAX);
    DECLARE @v_groupby           AS NVARCHAR(MAX);
    DECLARE @v_orderby           AS NVARCHAR(MAX);
    DECLARE @v_column_text       AS NVARCHAR(1000);
    DECLARE @v_column_name       AS NVARCHAR(50);
    DECLARE @v_column_date       AS NVARCHAR(50);
    DECLARE @v_column_type       AS NVARCHAR(50);
    DECLARE @v_column_value      AS NVARCHAR(50);  
    DECLARE @v_sort_order_no     AS NVARCHAR(50);
    DECLARE @v_day_code          AS NVARCHAR(50);  
    DECLARE @p_param_list        AS NVARCHAR(4000);
    DECLARE @p_end_week          AS NVARCHAR(6);
    DECLARE @v_program_id        AS NVARCHAR(10);
    DECLARE @v_sheet_name        AS NVARCHAR(100);
    DECLARE @v_groupby_column    AS NVARCHAR(100);
    DECLARE @v_from_yyyymmdd     AS NVARCHAR(8);
    DECLARE @v_to_yyyymmdd       AS NVARCHAR(8);
    DECLARE @v_from_result       AS NVARCHAR(8);
    DECLARE @v_to_result         AS NVARCHAR(8);
    DECLARE @v_user_col_cnt      AS INT;
	DECLARE @v_user_mea_cnt      AS INT;
	DECLARE @v_dept_id           AS NVARCHAR(50);  
	DECLARE @v_user_time_zone    AS NVARCHAR(50);  
  
    
	SET @v_dept_id = '';
	
	IF @p_user_group IN ( 'DM ADMIN', 'ADMIN' )
		BEGIN
		    SET @v_dept_id = 'ALL';
			
		END;
    ELSE
	    BEGIN
		    /*
			SELECT @v_dept_id = U.DEPT_ID
			FROM   [dbo].[TB_FX_User] U
			WHERE  U.UserID = @p_created_by;
			*/
			SELECT @v_dept_id = isnull((SELECT SEGMENT3
