  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_scm_site_id_t]'  , [dbo].[FN_SCM_GET_WHERE_SQL]('T.SCM_SITE_ID'  , 'IN', @p_scm_site_id)); 
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_plant_site_id_t]', [dbo].[FN_SCM_GET_WHERE_SQL]('T.PLANT_SITE_ID', 'IN', @p_plant_site_id));
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_project_code_t]' , [dbo].[FN_SCM_GET_WHERE_SQL]('T.PROJECT_CODE', 'LK', @p_project_code));  
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_item_id_t]'      , [dbo].[FN_SCM_GET_WHERE_SQL]('T.ITEM_ID', 'LK', @p_item_id)); 
