  SET @v_sql_text = R

/****************************************************************************************************/
/* Program ID  : DM0003_GET_MKT_FCST_DATA                                                             */
/* Description : Procedure 작성 가이드                                                              */
/* Usage       : Procedure 작성 시 참조하세요!                                                      */
/* Parameter   :                                                                                    */
/*                                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2017/11/24  SongDH       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트 */
/*                                                                                                  */
/****************************************************************************************************/
CREATE procedure [dbo].[DM0003_GET_MKT_FCST_DATA_XML]
    @p_division_id    NVARCHAR(MAX),
    @p_scm_site_id    NVARCHAR(MAX),
    @p_plant_site_id  NVARCHAR(MAX),
    @p_team_id        NVARCHAR(MAX),
    @p_customer       NVARCHAR(MAX),
    @p_biz_type       NVARCHAR(MAX),
    @p_project_code   NVARCHAR(MAX),
    @p_item_id        NVARCHAR(MAX),
    @p_from_yyyymmdd  NVARCHAR(8),
    @p_to_yyyymmdd    NVARCHAR(8),
    @p_created_by	  NVARCHAR(50),
	@p_user_group     NVARCHAR(50),
	@p_item_type      NVARCHAR(MAX)
  --,@p_debug         NVARCHAR(MAX) OUTPUT
AS  
  
BEGIN
    SET NOCOUNT ON;

    DECLARE @v_sql_text_result   AS NVARCHAR(MAX);
    DECLARE @v_sql_text          AS NVARCHAR(MAX);
    DECLARE @v_sql_text3         AS NVARCHAR(MAX);
    DECLARE @v_iteration         AS NVARCHAR(MAX);
    DECLARE @v_column            AS NVARCHAR(MAX);
    DECLARE @v_groupby           AS NVARCHAR(MAX);
    DECLARE @v_orderby           AS NVARCHAR(MAX);
    DECLARE @v_column_text       AS NVARCHAR(1000);
    DECLARE @v_column_name       AS NVARCHAR(50);
    DECLARE @v_column_date       AS NVARCHAR(50);
    DECLARE @v_column_type       AS NVARCHAR(50);
    DECLARE @v_column_value      AS NVARCHAR(50);  
    DECLARE @v_sort_order_no     AS NVARCHAR(50);
    DECLARE @v_day_code          AS NVARCHAR(50);  
    DECLARE @p_param_list        AS NVARCHAR(4000);
    DECLARE @p_end_week          AS NVARCHAR(6);
    DECLARE @v_program_id        AS NVARCHAR(10);
    DECLARE @v_sheet_name        AS NVARCHAR(100);
    DECLARE @v_groupby_column    AS NVARCHAR(100);
    DECLARE @v_from_yyyymmdd     AS NVARCHAR(8);
    DECLARE @v_to_yyyymmdd       AS NVARCHAR(8);
    DECLARE @v_from_result       AS NVARCHAR(8);
    DECLARE @v_to_result         AS NVARCHAR(8);
    DECLARE @v_user_col_cnt      AS INT;
	DECLARE @v_user_mea_cnt      AS INT;
	DECLARE @v_dept_id           AS NVARCHAR(50);  
	DECLARE @v_user_time_zone    AS NVARCHAR(50);  
  
    
	SET @v_dept_id = '';
	
	IF @p_user_group IN ( 'DM ADMIN', 'ADMIN' )
		BEGIN
		    SET @v_dept_id = 'ALL';
			
		END;
    ELSE
	    BEGIN
		    /*
			SELECT @v_dept_id = U.DEPT_ID
			FROM   [dbo].[TB_FX_User] U
			WHERE  U.UserID = @p_created_by;
			*/
			SELECT @v_dept_id = isnull((SELECT SEGMENT3
						                FROM   [dbo].[SCM_ADM_LOOKUP_MASTER_DETAIL]
						                WHERE  LOOKUP_TYPE = 'PM_TEAM_MAPPING'
							            AND   SEGMENT1    = U.DEPT_ID 
									   ) , U.DEPT_ID )
			FROM   [dbo].[TB_FX_User] U
			WHERE  U.UserID = @p_created_by

		END;

	DECLARE c_bucket CURSOR FAST_FORWARD FOR 
		SELECT 'D_' + a.basis_yyyymmdd  AS column_name
			 , a.basis_yyyymmdd         AS column_date
			 , 'F.YYYYMMDD'             AS col

ET @v_orderby = ' ORDER BY F.' + @v_column_name;
		END;
	ELSE
	     BEGIN
		--IF @v_column_name = 'TOTAL_SUM'
		--	BEGIN
		--	SET @v_column = @v_column + ', SUM(F.QTY) AS ' + @v_column_name;
		--	END;
		--ELSE
		--  BEGIN
		--	SET @v_column = @v_column + ', F.' + @v_column_name;
		--	SET @v_groupby = @v_groupby + ', F.' + @v_column_name;
		--	SET @v_orderby = @v_orderby + ', F.' + @v_column_name;
		--	END;
			SET @v_column = @v_column + ', F.' + @v_column_name;
			SET @v_groupby = @v_groupby + ', F.' + @v_column_name;
			SET @v_orderby = @v_orderby + ', F.' + @v_column_name;
        END;
	--SELECT @v_iteration = @v_iteration + @v_column_text;	
    
    FETCH NEXT FROM c_title INTO @v_program_id, @v_sheet_name, @v_column_name, @v_sort_order_no
  END;
  
  --Measure Sort Order No로 Sort
  SET @v_column =  REPLACE(@v_column, 'F.MEASURE,', 'U.MEASURE,' );
  SET @v_column =  REPLACE(@v_column, 'F.MEASURE_GROUP,', 'ISNULL( ( SELECT MAX(COLUMN_LABEL_NAME)  FROM [dbo].[SCM_MST_SHEET_MEASURE] where PROGRAM_ID = ''DM0003'' and COLUMN_NAME = U.MEASURE_GROUP ), U.MEASURE_GROUP ) AS MEASURE_GROUP,' );
  --SET @v_column =  REPLACE(@v_column, 'F.MEASURE', 'ISNULL( ( SELECT MAX(COLUMN_LABEL_NAME)  FROM [dbo].[SCM_MST_SHEET_MEASURE] where PROGRAM_ID = ''DM0003'' and COLUMN_NAME = U.MEASURE), ''  ''+U.MEASURE ) AS MEASURE' );
 
  SET @v_groupby = REPLACE(@v_groupby, 'F.MEASURE', 'U.MEASURE' );
  SET @v_column =  REPLACE(@v_column, 'F.MEASURE', 'U.MEASURE' );

  SET @v_groupby = @v_groupby + ', F.EDIT_FLAG, U.SORT_ORDER_NO';
  --SET @v_orderby = REPLACE(@v_orderby, 'MEASURE', 'U.SORT_ORDER_NO');
  SET @v_orderby = REPLACE(@v_orderby, 'F.MEASURE_GROUP', 'U.SORT_ORDER_NO');
  SET @v_orderby = REPLACE(@v_orderby, ', F.MEASURE', '');

  --SELECT @v_column;
  --SELECT @v_groupby;

  CLOSE c_title;  
  DEALLOCATE c_title;

  SET @v_from_yyyymmdd  = '';
  SET @v_to_yyyymmdd    = '';
  SET @v_from_result    = '';
  SET @v_to_result      = '';
  SET @v_user_time_zone = '';

  --SET @v_from_yyyymmdd = CONVERT(NVARCHAR(8), CURRENT_TIMESTAMP, 112);

  --SELECT @v_from_yyyymmdd = C.BASIS_START_DATE
  --FROM   [dbo].[SCM_SYS_CALENDAR_M]      C	
  --WHERE  1 = 1
  --AND    C.BASIS_YYYYMMDD = CONVERT(NVARCHAR(8), CURRENT_TIMESTAMP, 112) 

  BEGIN
	  SELECT @v_user_time_zone = U.TIMEZONE
	  FROM   [dbo].[TB_FX_User] U
	  WHERE  U.UserID = @p_created_by;
  END

  SELECT @v_from_yyyymmdd = MIN(C.BASIS_YYYYMMDD)
  FROM   [dbo].[SCM_SYS_CALENDAR_M] C  WITH(NOLOCK) 
       , (SELECT DISTINCT ISO_YYYYWW		    		
	      FROM   [dbo].[SCM_SYS_CALENDAR_M] WITH(NOLOCK) 
		  WHERE  1 = 1
		  AND    BASIS_YYYYMMDD = CONVERT(CHAR(8), dbo.FN_MULTY_TIME(@v_user_time_zone), 112)
		  --AND    BASIS_YYYYMMDD <= CONVERT(CHAR(8), DATEADD(MM, @v_user_col_cnt, dbo.FN_MULTY_TIME(@v_user_time_zone)), 112)
		 ) T
  WHERE  1 = 1
  AND    C.ISO_YYYYWW = T.ISO_YYYYWW ;


  SELECT @v_from_result = C.BASIS_START_DATE
  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C	
  WHERE  1 = 1
  AND    C.BASIS_YYYYMMDD = @p_from_yyyymmdd; 

  SELECT @v_to_result = C.BASIS_START_DATE
  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C	
  WHERE  1 = 1
  AND    C.BASIS_YYYYMMDD = @p_to_yyyymmdd; 

  IF @v_from_yyyymmdd > @v_from_result
      BEGIN -- 실적 보여줌
	  SET @v_to_yyyymmdd   = @p_to_yyyymmdd;
      SET @v_to_result     = @v_from_yyyymmdd;
	  END;
  ELSE IF @v_from_yyyymmdd <= @v_from_result
      BEGIN -- 실적 없음
	  SET @v_to_yyyymmdd   = @p_to_yyyymmdd;
	  SET @v_from_result = '19000101'; --CONVERT(CHAR(8), DATEADD(MM, 6, CURRENT_TIMESTAMP), 112);
      SET @v_to_result = '19000101'; --CONVERT(CHAR(8), DATEADD(MM, -6, CURRENT_TIMESTAMP), 112);
	  END;
  ELSE IF @v_from_yyyymmdd > @v_to_result
      BEGIN -- 실적만 보여줌
	  SET @v_from_yyyymmdd = '19000101'; --CONVERT(CHAR(8), DATEADD(MM, 6, CURRENT_TIMESTAMP), 112);
      SET @v_to_yyyymmdd = '19000101'; --CONVERT(CHAR(8), DATEADD(MM, -6, CURRENT_TIMESTAMP), 112);
	  SET @v_fro

