    DECLARE @v_sheet_name        AS NVARCHAR(100);
    DECLARE @v_groupby_column    AS NVARCHAR(100);
    DECLARE @v_from_yyyymmdd     AS NVARCHAR(8);
    DECLARE @v_to_yyyymmdd       AS NVARCHAR(8);
    DECLARE @v_from_result       AS NVARCHAR(8);
    DECLARE @v_to_result         AS NVARCHAR(8);
    DECLARE @v_user_col_cnt      AS INT;
	DECLARE @v_user_mea_cnt      AS INT;
	DECLARE @v_dept_id           AS NVARCHAR(50);  
	DECLARE @v_user_time_zone    AS NVARCHAR(50);  
  
	----20180626, lsh
	DECLARE @v_owner_sml_text	 AS NVARCHAR(MAX);
	DECLARE @v_owner_def_text	 AS NVARCHAR(MAX);


	SET @v_dept_id = '';
	DECLARE @v_group_id nvarchar(max)='';

	IF @p_user_group = 'ADMIN' OR @p_user_group = 'DM ADMIN'
		SET @v_group_id = 'ADMIN'
	/*
	-- 여러 팀 수정 권한으로 주석처리. 20180525
	
	IF @p_user_group IN ( 'DM ADMIN', 'ADMIN' )
		BEGIN
		    SET @v_dept_id = 'ALL';
			
		END;
    ELSE
	    BEGIN
		    /*
			SELECT @v_dept_id = U.DEPT_ID
			FROM   [dbo].[TB_FX_User] U
			WHERE  U.UserI

URE_GROUP,' );
  --SET @v_column =  REPLACE(@v_column, 'F.MEASURE', 'ISNULL( ( SELECT MAX(COLUMN_LABEL_NAME)  FROM [dbo].[SCM_MST_SHEET_MEASURE] where PROGRAM_ID = ''DM0003'' and COLUMN_NAME = U.MEASURE), ''  ''+U.MEASURE ) AS MEASURE' );
 
  SET @v_groupby = REPLACE(@v_groupby, 'F.MEASURE', 'U.MEASURE' );
  SET @v_column =  REPLACE(@v_column, 'F.MEASURE', 'U.MEASURE' );

  SET @v_groupby = @v_groupby + ', F.EDIT_FLAG, U.SORT_ORDER_NO';
  --SET @v_orderby = REPLACE(@v_orderby, 'MEASURE', 'U.SORT_ORDER_NO');
  SET @v_orderby = REPLACE(@v_orderby, 'F.MEASURE_GROUP', 'U.SORT_ORDER_NO');
  SET @v_orderby = REPLACE(@v_orderby, ', F.MEASURE', '');

  --SELECT @v_column;
  --SELECT @v_groupby;

  CLOSE c_title;  
  DEALLOCATE c_title;

  SET @v_from_yyyymmdd  = '';
  SET @v_to_yyyymmdd    = '';
  SET @v_from_result    = '';
  SET @v_to_result      = '';
  SET @v_user_time_zone = '';

  --SET @v_from_yyyymmdd = CONVERT(NVARCHAR(8), CURRENT_TIMESTAMP, 112);

  --SELECT @v_from_yyyymmdd = C.BASIS_START_DATE
  --FROM   [dbo].[SCM_SYS_CALENDAR_M]      C	
  --WHERE  1 = 1
  --AND    C.BASIS_YYYYMMDD = CONVERT(NVARCHAR(8), CURRENT_TIMESTAMP, 112) 

  BEGIN
	  SELECT @v_user_time_zone = U.TIMEZONE
	  FROM   [dbo].[TB_FX_User] U WITH(NOLOCK)
	  WHERE  U.UserID = @p_created_by;
  END

  SELECT @v_from_yyyymmdd = MIN(C.BASIS_YYYYMMDD)
  FROM   [dbo].[SCM_SYS_CALENDAR_M] C  WITH(NOLOCK) 
       , (SELECT DISTINCT ISO_YYYYWW		    		
	      FROM   [dbo].[SCM_SYS_CALENDAR_M] WITH(NOLOCK) 
		  WHERE  1 = 1
		  AND    BASIS_YYYYMMDD = CONVERT(CHAR(8), dbo.FN_MULTY_TIME(@v_user_time_zone), 112)
		  --AND    BASIS_YYYYMMDD <= CONVERT(CHAR(8), DATEADD(MM, @v_user_col_cnt, dbo.FN_MULTY_TIME(@v_user_time_zone)), 112)
		 ) T
  WHERE  1 = 1
  AND    C.ISO_YYYYWW = T.ISO_YYYYWW ;


  SELECT @v_from_result = C.BASIS_START_DATE
  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C	WITH(NOLOCK)
  WHERE  1 = 1
  AND    C.BASIS_YYYYMMDD = @p_from_yyyymmdd; 

  SELECT @v_to_result = C.BASIS_START_DATE
  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C	WITH(NOLOCK)
  WHERE  1 = 1
  AND    C.BASIS_YYYYMMDD = @p_to_yyyymmdd; 

  IF @v_from_yyyymmdd > @v_from_result
      BEGIN -- 실적 보여줌
	  SET @v_to_yyyymmdd   = @p_to_yyyymmdd;
      SET @v_to_result     = @v_from_yyyymmdd;
	  END;
  ELSE IF @v_from_yyyymmdd <= @v_from_result
      BEGIN -- 실적 없음
	  SET @v_to_yyyymmdd   = @p_to_yyyymmdd;
	  SET @v_from_result = '19000101'; --CONVERT(CHAR(8), DATEADD(MM, 6, CURRENT_TIMESTAMP), 112);
      SET @v_to_result = '19000101'; --CONVERT(CHAR(8), DATEADD(MM, -6, CURRENT_TIMESTAMP), 112);
	  END;
  ELSE IF @v_from_yyyymmdd > @v_to_result
      BEGIN -- 실적만 보여줌
	  SET @v_from_yyyymmdd = '19000101'; --CONVERT(CHAR(8), DATEADD(MM, 6, CURRENT_TIMESTAMP), 112);
      SET @v_to_yyyymmdd = '19000101'; --CONVERT(CHAR(8), DATEADD(MM, -6, CURRENT_TIMESTAMP), 112);
	  SET @v_from_result = @p_from_yyyymmdd;
	  SET @v_to_result = @p_to_yyyymmdd;
	  END;
  ELSE IF @v_from_yyyymmdd = @v_to_result
      BEGIN
      SET @v_to_yyyymmdd = @v_from_yyyymmdd
	  SET @v_from_result = @p_from_yyyymmdd;
	  SET @v_to_result = @p_to_yyyymmdd;
	  END;

	 
  SET @v_sql_text = '
WITH SELECT_MEASURE AS (SELECT U.PROGRAM_ID
                             , U.SHEET_NAME
                             , U.USER_ID
                             --, U.COLUMN_NAME AS MEASURE_GROUP
                         , CASE WHEN U.COLUMN_NAME IN ( ''CUST_INV_I'',''CUST_PRODUCT_S'',''CUST_WHIN_P'',''CUST_DIO''  )  THEN ''CUST. PSI'' 
                                WHEN  U.COLUMN_NAME IN ( ''MKT_INV_I'',''MKT_PRODUCT_S'',''MKT_WHIN_P'',''MKT_DIO''  )  THEN ''MKT PSI''  
                              ELSE   U.COLUMN_NAME 
                           END AS MEASURE_GROUP
                         , U.COLUMN_NAME AS MEASURE
                         , U.SORT_ORDER_NO
                          FROM [dbo].[SCM_MST_TITLESET_USER] U  WITH(NOLOCK,INDEX (PK_SCM_MST_TITLE

ET_WHERE_SQL]('F.PROJECT_CODE', 'LK', @p_project_code)); 
  ELSE
    SET @v_sql_text = REPLACE(@v_sql_text,'[@v_project_code]' , [dbo].[FN_SCM_GET_WHERE_SQL]('F.PROJECT_CODE', 'LK', @p_customer)); 
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_item_id]'      , [dbo].[FN_SCM_GET_WHERE_SQL]('F.ITEM_ID', 'LK', @p_item_id)); 

  ----20180626
  IF @p_owner = ''
	  begin
		  SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_def_text]', 'AND 1=1 ');
		  SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_sml_text]', 'AND 1=1 ');
	  end
  else
	  begin
  --SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_def_text]', 'AND EXISTS (SELECT * FROM [dbo].[UF_FX_STRING_SPLIT] (''ZZZZZ'','','') AS P WHERE b.PROJECT_OWNER LIKE N''%'' + P.token +''%'')');
  SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_def_text]', 'AND ( j.USER_ID IN ( SELECT token FROM dbo.String_Split(N'''+@p_owner+''','',''))  OR j.USER_NAME IN ( SELECT token FROM dbo.String_Split(N'''+@p_owner+''','',''))  OR j.USER_NAME_EN IN ( SELECT token FROM dbo.String_Split('''+@p_owner+''','','')) )   ' );
  SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_sml_text]',  ' AND    ( SU.USER_ID IN ( SELECT token FROM dbo.String_Split('''+@p_owner+''','','') ) OR SU.USER_NAME IN ( SELECT token FROM dbo.String_Split(N'''+@p_owner+''','','') ) OR SU.USER_NAME_EN IN ( SELECT token FROM dbo.String_Split('''+@p_owner+''','','') )  ) ' );
  SET @v_sql_text = REPLACE(@v_sql_text, 'ZZZZZ', @p_owner);
	  end

  --SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_def_text]', 'AND EXISTS (SELECT * FROM [dbo].[UF_FX_STRING_SPLIT] (''ZZZZZ'','','') AS P WHERE b.PROJECT_OWNER LIKE N''%'' + P.token +''%'')');
  --SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_sml_text]', 'AND EXISTS (SELECT * FROM [dbo].[UF_FX_STRING_SPLIT] (''ZZZZZ'' ,'','') AS P WHERE SI.OWNER LIKE N''%'' + P.token + ''%'')');
  --SET @v_sql_text = REPLACE(@v_sql_text, 'ZZZZZ', @p_owner);
  -- SET @v_sql_text = REPLACE(@v_sql_text, 'ZZZZZ', @p_owner);

  --  SET @v_sql_text = REPLACE(@v_sql_text, '[@v_owner_sml_text]', @p_owner);

  ------------------------------------------------------------------------------------------------------------------------------*****

  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_division_id_t]'  , [dbo].[FN_SCM_GET_WHERE_SQL]('T.DIVISION_ID'  , 'IN', @p_division_id));
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_scm_site_id_t]'  , [dbo].[FN_SCM_GET_WHERE_SQL]('T.SCM_SITE_ID'  , 'IN', @p_scm_site_id)); 
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_plant_site_id_t]', [dbo].[FN_SCM_GET_WHERE_SQL]('T.PLANT_SITE_ID', 'IN', @p_plant_site_id));
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_project_code_t]' , [dbo].[FN_SCM_GET_WHERE_SQL]('T.PROJECT_CODE', 'LK', @p_project_code));  
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_item_id_t]'      , [dbo].[FN_SCM_GET_WHERE_SQL]('T.ITEM_ID', 'LK', @p_item_id)); 
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_item_type_I]'    , [dbo].[FN_SCM_GET_WHERE_SQL]('L.ITEM_TYPE'    , 'IN', @p_item_type  ));
  
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_from_yyyymmdd]', @v_from_yyyymmdd);
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_to_yyyymmdd]'  , @v_to_yyyymmdd  );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_from_result]'  , @v_from_result  );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_to_result]'    , @v_to_result    );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_column]'       , @v_column       );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_groupby]'      , @v_groupby      );
  --SET @v_sql_text = REPLACE(@v_sql_text,'[@v_orderby]'      , @v_orderby      );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@p_created_by]'   , @p_created_by   );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_dept_id]'      , @v_dept_id      );
  SET @v_sql_text = REPLACE(@v_sql_text,'[@v_group_id]'      , @v_group_id      );

  -- 0703 skh added
  SET @v_sql_text = REPLACE(@v_sql_text,'[@p_from_yyyymmdd]', @p_from_yyyymmdd);
  SET @v_sql_text = R

EPLACE(@v_sql_text,'[@p_to_yyyymmdd]', @p_to_yyyymmdd);
  
  
  --SET @p_debug = @v_iteration;
  --RETURN @p_debug;
  --SELECT @v_sql_text;
     
  --select @v_column_name, @v_column


	--select @v_column;
	--select @v_sql_text;
 EXEC SP_EXECUTESQL @v_sql_text; 

-- xml확인할경우
SELECT CONVERT(TEXT, @v_sql_text)
FOR XML PATH('')--,ROOT('x')  
 
END

